import subprocess, os, tempfile, json, re

def run(*a):
    r=subprocess.run(["./executable"]+list(a), capture_output=True, text=True)
    return r.stdout, r.stderr, r.returncode

def count_for_file(fname, content, extra_args=[]):
    d=tempfile.mkdtemp()
    open(os.path.join(d,fname),"w").write(content)
    o=run(*(extra_args+["--format","json",d]))[0].strip()
    if o=="[]":
        return None
    try:
        return json.loads(o)[0]
    except:
        return None

# Load langs
with open("/tmp/langs.txt") as f:
    lines=f.read().strip().split("\n")
lang_ext={}
for l in lines:
    m=re.match(r"^(.*) \((.*)\)$", l)
    name=m.group(1)
    exts=[e.strip() for e in m.group(2).split(",") if e.strip()!=""]
    lang_ext[name]=exts

# Find working filename for each lang (for generic content)
# Use logic from earlier, but handle special cases
def find_fname(lang, exts):
    # try a.e for each ext
    for e in exts:
        for fname in [f"a.{e}", f"a.{e.lower()}"]:
            j=count_for_file(fname, "x\n")
            if j and j["Name"]==lang:
                return fname
    # try filename e (for Dockerfile etc)
    for e in exts:
        for fname in [e, e.lower(), e.upper()]:
            # skip if fname contains dot? For meson.build etc, fname is full name
            j=count_for_file(fname, "x\n")
            if j and j["Name"]==lang:
                return fname
    # special: gitignore, ignore need --count-ignore
    for e in exts:
        for fname in [f"a.{e}", e]:
            j=count_for_file(fname, "x\n", ["--count-ignore"])
            if j and j["Name"]==lang:
                return (fname, ["--count-ignore"])
    # special: Objective C needs content
    if lang=="Objective C":
        return ("a.m", None, "@interface X\n")  # prefix?
    if lang=="V":
        return ("a.v", None, "fn main() {}\n")
    if lang=="Verilog":
        return ("a.v", None, "module x\n")
    if lang=="CloudFormation (JSON)":
        return None
    if lang=="CloudFormation (YAML)":
        return None
    if lang in ["LaTeX"]:
        return None
    return None

# Test find for all
results={}
for lang, exts in lang_ext.items():
    f=find_fname(lang, exts)
    results[lang]=f
    print(lang, f)

# Save
import json as js
with open("/tmp/fname_map.json","w") as out:
    js.dump(results, out, indent=2)
PY
