import subprocess, os, tempfile
def run(*a):
    r=subprocess.run(["/tmp/original_executable"]+list(a), capture_output=True, text=True)
    return r.stdout
def cycles(code, cx):
    d=tempfile.mkdtemp()
    # Create file with code lines and complexity: code lines = code, complexity = cx
    # For Go, "if x\n" gives 1 code, 1 cx per line. "x\n" gives 1 code, 0 cx.
    # To get code=N, cx=M (M<=N), use M lines "if x\n" + (N-M) lines "x\n"
    content="if x\n"*cx + "x\n"*(code-cx)
    open(os.path.join(d,"a.go"),"w").write(content)
    o=run("--locomo",d)
    for l in o.split("\n"):
        if "Cycles" in l:
            return l
    return None

for code,cx in [(10,0),(10,5),(10,10),(100,0),(100,50),(100,100),(8,3)]:
    print(f"code={code},cx={cx}: {cycles(code,cx)}")
